enum class FanousThemeId(val wire: String) {
    LANTERN("lantern"),
    ZUJAJ("zujaj"),
    NAHAS("nahas"),
    FAWANEES("fawanees");

    val tokens: FanousThemeTokens get() = FanousThemes.get(this)

    companion object {
        /** Shown when the site theme cannot be read and nothing is cached. */
        val FALLBACK = FAWANEES

        /** Any received value reduced to a theme this build knows, as the web does. */
        fun fromSite(value: String?): FanousThemeId = entries.firstOrNull { it.wire == value } ?: FALLBACK
    }
}

